CREATE TABLE public.push_subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, endpoint text NOT NULL UNIQUE, subscription jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,DELETE ON public.push_subscriptions TO authenticated; GRANT ALL ON public.push_subscriptions TO service_role; ALTER TABLE public.push_subscriptions ENABLE ROW LEVEL SECURITY; CREATE POLICY push_own_read ON public.push_subscriptions FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE POLICY push_own_insert ON public.push_subscriptions FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid()); CREATE POLICY push_own_delete ON public.push_subscriptions FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.push_keys(id text PRIMARY KEY DEFAULT 'vapid', public_key text NOT NULL, private_key jsonb NOT NULL); GRANT ALL ON public.push_keys TO service_role; ALTER TABLE public.push_keys ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.push_deliveries(subscription_id uuid NOT NULL REFERENCES public.push_subscriptions(id) ON DELETE CASCADE, event_key text NOT NULL, sent_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(subscription_id,event_key)); GRANT ALL ON public.push_deliveries TO service_role; ALTER TABLE public.push_deliveries ENABLE ROW LEVEL SECURITY;